void
process_bgp_update(netdissect_options *ndo, const u_char *dat, int length)
{
    const u_char *cp;
    u_int withdrawn_routes_length;
    u_int path_attributes_length;
    int hdrlen = 0;

    if (length < BGP_MSG_HEADER_LEN) {
        ND_PRINT((ndo, "[|bgp]"));
        return;
    }

    cp = dat;

    if (ndo->ndo_vflag >= 1) {
        ND_TCHECK(*cp);
        ND_PRINT((ndo, " BGP Update (length: %u)", length));
    }

    cp += hdrlen;

    withdrawn_routes_length = GET_U_2_BYTES(cp);
    cp += 2;
    length -= 2;

    if (length < withdrawn_routes_length) {
        ND_PRINT((ndo, "\n\t(truncated withdrawn routes, %u bytes missing)", withdrawn_routes_length - length));
        return;
    }

    if (withdrawn_routes_length == 0) {
        ND_PRINT((ndo, "\n\tWithdrawn Routes: None"));
    } else {
        ND_PRINT((ndo, "\n\tWithdrawn Routes: %u bytes", withdrawn_routes_length));
        if (withdrawn_routes_length > 0) {
            ND_TCHECK_LEN(cp, withdrawn_routes_length);
            ND_PRINT((ndo, ", data: %02x...", *cp));
        }
    }

    cp += withdrawn_routes_length;
    length -= withdrawn_routes_length;

    path_attributes_length = GET_U_2_BYTES(cp);
    cp += 2;
    length -= 2;

    if (length < path_attributes_length) {
        ND_PRINT((ndo, "\n\t(truncated path attributes, %u bytes missing)", path_attributes_length - length));
        return;
    }

    if (path_attributes_length == 0) {
        ND_PRINT((ndo, "\n\tPath Attributes: None"));
    } else {
        ND_PRINT((ndo, "\n\tPath Attributes: %u bytes", path_attributes_length));
        if (path_attributes_length > 0) {
            ND_TCHECK_LEN(cp, path_attributes_length);
            ND_PRINT((ndo, ", data: %02x...", *cp));
        }
    }

    cp += path_attributes_length;
    length -= path_attributes_length;

    if (length != 0) {
        ND_PRINT((ndo, "\n\t(truncated BGP Update message, %u bytes missing)", length));
    }

    ND_PRINT((ndo, "\n"));
}

