    ND_TCHECK(*dat);
    ND_PRINT((ndo, "BGP %u bytes, update message", length));

    cp += hdrlen;
    if (cp + 2 > ep) {
        ND_PRINT((ndo, "\n\t(truncated, can't read withdrawn routes length)"));
