void
process_bgp_update(netdissect_options *ndo, const u_char *dat, int length)
{
    const u_char *cp;
    uint16_t total_length;
    int orig_length;
    int withdrawn_routes_length;
    int path_attributes_length;

    ND_PRINT((ndo, "BGP update message:"));

    if (length < BGP_HEADERLEN) {
        ND_PRINT((ndo, " [|truncated]"));
        return;
    }

    ND_TCHECK(*dat);
    ND_PRINT((ndo, " (length %u)", length));

    cp = dat + BGP_HEADERLEN;
    total_length = GET_UINT16(cp);
    orig_length = length;
    length -= BGP_HEADERLEN;
    cp += 2;

    if (length < 2) {
        ND_PRINT((ndo, " [truncated]"));
        return;
    }

    withdrawn_routes_length = *cp++;
    length--;

    if (withdrawn_routes_length > length) {
        ND_PRINT((ndo, " [truncated]"));
        return;
    }

    if (withdrawn_routes_length > 0) {
        ND_PRINT((ndo, " Withdrawn routes (%d bytes):", withdrawn_routes_length));
        ND_TCHECK_LEN(cp, withdrawn_routes_length);
        ND_PRINT((ndo, " %s", taddrport_string(ndo, cp, withdrawn_routes_length, 0, 0)));
    } else {
        ND_PRINT((ndo, " No withdrawn routes"));
    }

    cp += withdrawn_routes_length;
    length -= withdrawn_routes_length;

    if (length < 2) {
        ND_PRINT((ndo, " [truncated]"));
        return;
    }

    path_attributes_length = *cp++;
    length--;

    if (path_attributes_length > length) {
        ND_PRINT((ndo, " [truncated]"));
        return;
    }

    if (path_attributes_length > 0) {
        ND_PRINT((ndo, " Path attributes (%d bytes):", path_attributes_length));
        ND_TCHECK_LEN(cp, path_attributes_length);
        ND_PRINT((ndo, " %s", taddrport_string(ndo, cp, path_attributes_length, 0, 0)));
    } else {
        ND_PRINT((ndo, " No path attributes"));
    }

    if (total_length != orig_length) {
        ND_PRINT((ndo, " [truncated]"));
    }
}

