void
process_bgp_update(netdissect_options *ndo, const u_char *dat, int length)
{
    const u_char *ptr;
    u_int16_t total_length;
    u_int16_t withdraw_length;
    int header_length = 3 * 4;  /* BGP header is 19 bytes (3x 4 bytes) */

    if (length < header_length) {
        ND_PRINT("%s", "Truncated BGP update message");
        return;
    }

    ptr = dat;
    total_length = GET_U_2(ptr + 2);

    if (total_length > length) {
        ND_PRINT("%s", "Truncated BGP update message");
        return;
    }

    ptr += header_length;

    withdraw_length = GET_U_2(ptr);
    ptr += 2;

    if (withdraw_length > 0) {
        ND_PRINT("Withdrawn routes: %u bytes", withdraw_length);
        ptr += withdraw_length;
    } else {
        ND_PRINT("%s", "No withdrawn routes");
    }

    if ((int)(ptr - dat) > length) {
        ND_PRINT("%s", "Truncated BGP update message");
        return;
    }

    ND_PRINT("%s", "Path attributes:");

    while (ptr < dat + length) {
        u_char attr_type;

        if (ptr + 1 > dat + length) {
            ND_PRINT("%s", "Truncated BGP update message");
            return;
        }

        attr_type = *ptr++;

        if (attr_type == 0) {
            ND_PRINT("%s", "End of path attributes");
            break;
        }

        if (ptr + 1 > dat + length) {
            ND_PRINT("%s", "Truncated BGP update message");
            return;
        }

        ND_PRINT("Attribute type: 0x%x", attr_type);
        ND_PRINT("Attribute length: %u", *ptr);
        ptr += 2;
    }

    if (ptr == dat + length) {
        ND_PRINT("%s", "Empty NLRI");
    }
}
